from author import *
c=C('全微分与复合函数求导')
S(c,'全微分与小变化近似',[R('模板',r'dz=f_x\,dx+f_y\,dy'),R('本题在点处求系数',r'z=x^2y,\quad(x,y)=(1,2):\quad dz=4dx+dy'),R('小变化',r'dx=0.01,\ dy=-0.02:\quad\Delta z\approx dz=0.02'),R('实际变化作核对',r'(1.01)^2\cdot1.98-2=0.019798')],[P('全微分把两个方向的小变化合在一条式子里。先分别求偏导，再乘对应的dx和dy相加；求某一点的全微分时，系数要代入该点。例题x平方乘y，在一、二处两个偏导是四和一，所以不是把原函数直接写进公式，而是得到四dx加dy。',[1,2],['先求偏导，再在点处取值','dx与dy各乘自己的系数']),P('代入横向增加零点零一、纵向减少零点零二，线性近似变化是零点零二。实际变化约零点零一九八，接近但不完全相同。题目写近似计算时才用这个近似关系；若问精确增量，应将新点函数值减旧点函数值，不能把全微分与精确增量在所有情况下直接画等号。',[3,4],['近似量与精确增量要区分','负的变化量代入时保留符号'])],['全微分与近似计算'])
S(c,'一参数复合函数：两条路径相加',[R('依赖关系',r'z=x^2+y^2,\quad x=t,\quad y=t^2'),R('链式法则',r'\frac{dz}{dt}=z_x\frac{dx}{dt}+z_y\frac{dy}{dt}'),R('计算',r'\frac{dz}{dt}=2t+4t^3,\qquad z^{\prime}(1)=6')],[P('先把自变量之间的依赖关系连起来。z通过x和y两条路径随t变化，所以两条贡献都要相加。先求z对x与对y的偏导，再分别乘x、y对t的导数。本题两项是二x乘一，以及二y乘二t；最后用x等于t、y等于t平方替换，得到二t加四t三次方。',[1,2],['沿每条依赖路径相乘，再把路径相加','求完以后代入x与y的表达式'],phase='branches',anchor='先把自变量之间的依赖关系连起来'),P('现在把两条路径的贡献汇合。代t为一得到六。还可以先把函数全部写成t：z等于t平方加t四次方，直接求导作核对。但面对抽象函数没有具体表达式时，依赖树的方法更稳妥。漏掉y这条路径，是把二元函数误当成一元函数处理的典型错误。',[3],['有具体表达式可直接代入核对','抽象函数仍按依赖树计算'],phase='merge',anchor='现在把两条路径的贡献汇合')],['复合函数链式法则'],visual=G('chain'))
S(c,'多参数复合函数与抽象偏导',[R('依赖关系',r'z=f(u,v),\quad u=x+y,\quad v=xy'),R('分别固定另一个自变量',r'z_x=f_u+yf_v,\qquad z_y=f_u+xf_v'),R('例题给定偏导值',r'f_u(3,2)=3,\quad f_v(3,2)=4,\quad(x,y)=(1,2)'),R('结果',r'z_x(1,2)=11,\qquad z_y(1,2)=7')],[P('这次最终自变量有x和y。求z对x时，y暂时不动；u对x是一个一，v对x是y，所以得到第二行左式。求z对y时，x暂时不动，最后一项换成x乘f对v。这里的f对u、f对v都是在中间变量u、v的取值处计算，不是在原来的x、y坐标处随意代值。',[1,2],['最终对谁求导，就固定另一个最终自变量','f的偏导值对应u、v坐标']),P('给定x为一、y为二，中间变量是三和二，因此正好使用题目给的两项偏导值三与四。对x的结果是三加二乘四，等于十一；对y是三加一乘四，等于七。写草稿时把最终点先转换成中间点，可以避免把题目提供的偏导数据拿错位置。',[3,4],['先把最终点换成中间点','本题结果十一与七'])],['多参数链式法则','抽象函数求导'])
S(c,'隐函数：由方程求偏导',[R('隐式关系与适用条件',r'F(x,y,z)=0,\quad F_z\neq0'),R('模板',r'z_x=-\frac{F_x}{F_z},\qquad z_y=-\frac{F_y}{F_z}'),R('球面在指定点',r'x^2+y^2+z^2=9,\quad(1,2,2)'),R('代入',r'z_x=-\frac{x}{z}=-\frac12,\qquad z_y=-\frac{y}{z}=-1')],[P('有些题没有直接给z的表达式，而是用一个方程联系三个变量。若方程足够光滑，并且对z的偏导不为零，局部可以把z看成x、y的函数。模板是负的F对x除以F对z，另一条换成对y。这里求F的偏导时，三个坐标先按独立变量处理，不要把隐函数的导数混进分子。',[1,2],['分母是准备解出的那个变量的偏导','两个模板前面都有负号']),P('本题球面方程在一、二、二处成立，F对z是二z，取值四，不为零。分子分别是二x、二y，约分后得到负x除以z、负y除以z，所以是负二分之一与负一。若在某点分母为零，当前模板不能直接使用，也不能把零分母约掉后装作满足了适用条件。',[3,4],['先确认给定点在曲面上','分母为零时不能硬套当前模板'])],['多元隐函数求导'])
S(c,'曲面切平面与法线',[R('给定曲面与点',r'x^2+y^2+z^2=9,\quad M=(1,2,2)'),R('梯度作法向，写切平面',r'\nabla F=(2,4,4),\quad x+2y+2z=9'),R('法线的方向',r'(x,y,z)=(1,2,2)+t(1,2,2)')],[P('先把球面上的点与法向箭头标出来。光滑等值面的梯度垂直于切平面，所以可以直接用F的梯度当法向。本题在给定点梯度是二、四、四，整体除以二得到一、二、二，代点法式，展开后就是x加二y加二z等于九。法向整体缩放，不会改变平面。',[1,2],['梯度非零时可作切平面的法向','方程展开后用给定点自查'],phase='normal',anchor='先把球面上的点与法向箭头标出来'),P('现在让法线沿这个方向穿过切平面。法线是过给定点、方向与法向一致的一条直线，所以用点加t乘一、二、二写参数式。不要把切平面的两条切向当成法线方向。若题目直接给z等于f，也可以用z减z零等于f对x乘x差，加f对y乘y差，写出同一个切平面。',[3],['切平面用法向，法线沿法向','点加参数乘方向向量'],phase='tangent',anchor='现在让法线沿这个方向穿过切平面')],['曲面切平面与法线'],visual=G('tangent3'))
S(c,'方向导数与梯度的计算',[R('给定点的梯度',r'f=x^2+2y^2,\quad\nabla f(1,1)=(2,4)'),R('方向必须单位化',r'\mathbf e=\left(\frac35,\frac45\right),\quad D_{\mathbf e}f=\nabla f\cdot\mathbf e=\frac{22}{5}'),R('最大方向导数',r'\max D_{\mathbf e}f=|\nabla f|=2\sqrt5')],[P('先画出题目指定的方向。方向导数是在单位方向上测变化率，题目给三、四这样的方向向量时，要先除以长度五。再求点处梯度二、四，与五分之三、五分之四做点积，得到二十二除以五。这里使用梯度点乘公式，需要函数在目标点可微，本例多项式满足。',[1,2],['先单位化，不能直接点乘三、四','偏导先代入给定点'],phase='given',anchor='先画出题目指定的方向'),P('再把方向转到梯度方向。所有单位方向里，梯度方向的方向导数最大，数值是梯度长度二倍根号五；反方向得到最小值。若梯度为零，这个公式给出所有方向导数为零，但不代表函数在附近恒定，也不能单凭它判定极值。方向题、极值题虽然都用偏导，最后的判断任务不同。',[3],['最大变化率是梯度的长度','梯度为零不能直接判极值'],phase='maximum',anchor='再把方向转到梯度方向')],['梯度与方向导数'],visual=G('gradient'))
S(c,'复合函数求导练习',[R('依赖关系',r'z=f(x^2,xy),\quad (x,y)=(1,2)'),R('给定中间点偏导',r'f_u(1,2)=3,\qquad f_v(1,2)=4'),R('任务',r'z_x(1,2)=\ ?')],[P('暂停练习：z等于f作用在x平方和xy上，求一、二处对x的偏导。题目给中间点一、二处的两项偏导，分别是三和四。先写两条路径，再在每条路径上相乘，最后相加。特别注意，x平方对x的导数是二x，不是上一页x加y那道题里的一个一。',[1,2,3],['先写通式，确认中间点匹配','别把相似例题的内部导数照搬'])],['复合函数链式法则'],kind='question')
S(c,'复合函数求导练习答案',[R('链式法则',r'z_x=2x f_u+yf_v'),R('代入',r'z_x(1,2)=2\cdot1\cdot3+2\cdot4=14')],[P('答案是十四。第一条路径是f对u乘二x，第二条路径是f对v乘y。给定最终点一、二对应的中间点也是一、二，因此用三和四，算出六加八等于十四。如果算成十一，多半是把内部的x平方误当成x加y，少乘了一个二；相似题最需要检查依赖关系有没有变化。',[1,2],['两条路径分别得到六与八','先看内部函数，不能背上一题结果'])],['复合函数链式法则'],kind='answer')

c=C('多元函数极值与约束极值')
S(c,'驻点：先解两个偏导为零',[R('例题',r'f=x^2+y^2-2x-4y'),R('内部驻点候选',r'f_x=2x-2=0,\qquad f_y=2y-4=0'),R('候选点',r'(x,y)=(1,2)'),T('范围提醒','内部可微极值点必为驻点；还要检查不可微点及边界')],[P('无约束的二元极值题，先确定定义域，再求两个一阶偏导，并联立等于零。例题得到二x减二等于零、二y减四等于零，所以候选点是一、二。这一步只找候选位置，不是已经判断它为极大还是极小。若函数有不可微点，它也可能成为极值候选，不能直接漏掉。',[1,2,3],['先定义域，再联立两个偏导','驻点只是候选，不是最终结论']),P('必要条件的说法要完整：内部的可微极值点，一阶偏导应为零。边界点不一定满足这两条方程，有范围约束时必须另查边界。没有范围约束时，也不能把局部极值与整个定义域上的最大最小值混为一谈。先按题目要求决定找局部极值，还是找全局最值，再继续下一步。',[4],['内部条件不能直接套边界','局部极值与全局最值分别判断'])],['驻点与极值候选'])
S(c,'二阶判别：记住判别量与符号',[R('在驻点处计算',r'A=f_{xx},\quad B=f_{xy},\quad C=f_{yy},\quad D=AC-B^2'),R('判别量大于零',r'D>0:\quad A>0\ \Rightarrow\ \min;\quad A<0\ \Rightarrow\ \max'),T('其余情况','D<0：鞍点；D=0：本判别法无法判定')],[P('二阶判别适用于相应二阶偏导在邻域连续的情况，所有数值都在驻点处计算。先记A、B、C分别是xx、xy、yy，再组成A乘C减B平方。不是加B平方，也不是只比较A和C的正负。判别量大于零时，再看A，A正是极小，A负是极大。',[1,2],['D等于AC减B平方','先看D，再看A；都在驻点取值']),P('判别量小于零，对应鞍点，也就是附近既能变大又能变小，不是极值。判别量等于零时，这套规则没有给出结论，必须另用函数性质或定义判断，不能写成没有极值。记忆时把三种情况分开，尤其最后的无法判定，是考试里经常故意设置的选项。',[3],['D小于零是鞍点','D等于零只能说此法无法判定'])],['二阶极值判别'])
S(c,'二阶判别例题：极小值',[R('回到候选点',r'f=x^2+y^2-2x-4y,\quad (1,2)'),R('二阶数据',r'A=2,\quad B=0,\quad C=2,\quad D=4>0'),R('结论与函数值',r'f(1,2)=-5,\qquad f=(x-1)^2+(y-2)^2-5')],[P('先看驻点附近的碗形图。这个函数的二阶偏导是二、零、二，所以判别量四为正，再看A也为正，得到极小点是一、二。但题目若问极小值，还必须把坐标代回原函数，结果负五。极小点是坐标，极小值是一个函数值，两种答案形式不能只交一半。',[1,2],['D为正且A为正，判极小','问点给坐标，问值代回原函数'],phase='bowl',anchor='先看驻点附近的碗形图'),P('现在把最低点的位置标出来。配方以后，两项平方都非负，因此不只说明它是局部极小，也能确认负五是整个平面上的最小值。注意这是本题额外拥有的结构，不是所有二阶判别出的局部极小都自动为全局最小。若题目没有这种证据，就只写已经证明的局部结论。',[3],['本题配方可进一步确认全局最小','不能把局部结论普遍升级'],phase='minimum',anchor='现在把最低点的位置标出来')],['二阶极值判别','极值与最值'],visual=G('extrema'))
S(c,'判别量为零时，用反例辨别',[R('两个函数在原点二阶数据均为零',r'f=x^4+y^4,\qquad g=x^4-y^4'),R('第一个函数',r'f\geq0,\quad f(0,0)=0:\quad\min'),R('第二个函数的两条路径',r'g(x,0)=x^4>0,\quad g(0,y)=-y^4<0')],[P('先看两项四次方相加的函数。它在原点的二阶判别量为零，但函数总是非负，并且原点取零，所以仍是极小值。这说明判别量等于零，不代表没有极值。此时可以检查原式的符号、配方，或者寻找其他能直接比较函数值的方法，而不是反复套失效的二阶规则。',[1,2],['D等于零不代表没有极值','检查函数与候选值的大小关系'],phase='quartic',anchor='先看两项四次方相加的函数'),P('再看四次方相减的函数。沿横轴靠近原点得到正值，沿纵轴靠近得到负值，因此原点附近两边都有，不是极值。这两个例子二阶数据一样，结果却不同，正好说明为什么必须写无法判定。选择题遇到绝对化结论，可以用这样的简单多项式快速检查它是否可靠。',[3],['附近既有正值又有负值，不是极值','反例用来检查绝对化命题'],phase='saddle',anchor='再看四次方相减的函数')],['二阶判别退化情形'],visual=G('degenerate'))
S(c,'拉格朗日乘子：约束要一起联立',[R('题目与范围',r'f=xy,\quad x+y=2,\quad x,y\geq0'),R('内部候选',r'y=\lambda,\quad x=\lambda,\quad x+y=2'),R('候选与边界比较',r'(1,1):f=1;\qquad (0,2),(2,0):f=0')],[P('有等式约束时，可以使用拉格朗日乘子法。把目标函数的梯度设为λ乘约束函数的梯度，再把原约束一起联立。这里目标xy，约束x加y减二，得到y等于λ、x等于λ，以及x加y等于二。三条方程一起解，得到内部候选点一、一，目标值一。',[1,2],['梯度方程必须连同原约束','选用正负λ约定均可，但前后一致']),P('题目还给非负范围，所以允许点是一条闭线段，两个端点不能漏。比较得到最大值一，最小值零。如果只看等式约束、让x和y任意取实数，最小值就不存在，因为乘积可以不断变负。条件稍有改变，结论就不同；先抄清范围，再列候选和边界，比只背乘子公式更可靠。',[3],['闭线段的两个端点也要检查','本题非负条件影响最小值是否存在'])],['拉格朗日乘子与边界'])
S(c,'闭区域最值：内部与边界都查',[R('题目',r'f=x+y,\qquad x^2+y^2\leq1'),R('内部无驻点，边界参数化',r'(f_x,f_y)=(1,1),\quad x=\cos t,\ y=\sin t'),R('边界比较',r'f=\sqrt2\sin\left(t+\frac\pi4\right),\quad f_{\max}=\sqrt2,\quad f_{\min}=-\sqrt2')],[P('先把闭圆盘和目标方向标在图上。连续函数在闭有界区域上能取得最大最小值，计算时分内部和边界。本题两个偏导一直为一，内部没有驻点；边界是单位圆，可以设x等于余弦t、y等于正弦t，把问题变成一个参数的一元最值题，参数要走完整个圆周。',[1,2],['内部与边界都列入候选','参数范围覆盖整条边界'],phase='disk',anchor='先把闭圆盘和目标方向标在图上'),P('现在沿目标增加的方向找到最远位置。余弦t加正弦t的最大值根号二，最小值负根号二。达到最大值的点是两个坐标都为根号二的一半，最小值取它的相反点。也可用不等式或乘子法核对，但最终应写清最值以及对应点，别只报一条边界驻点方程就结束。',[3],['最大点与最小点互为相反点','值与达到该值的点配套写'],phase='maximum',anchor='现在沿目标增加的方向找到最远位置')],['闭区域最值'],visual=G('disk_extreme'))
S(c,'极值判别练习',[R('函数',r'f=x^2-y^2'),T('任务','原点为驻点，判断其类型与是否为极值点')],[P('暂停判断：函数x平方减y平方，在原点两个一阶偏导都是零。请计算三个二阶数据和判别量，并判断原点是不是极值点。先按二阶模板走一遍，再用沿x轴、沿y轴的函数符号核对一次。这样即使公式的正负顺序暂时忘了，也能发现不合理的结论。',[1,2],['先算AC减B平方','再沿两个坐标方向检查大小变化'])],['二阶极值判别'],kind='question')
S(c,'极值判别练习答案',[R('二阶数据',r'A=2,\quad B=0,\quad C=-2,\quad D=-4'),R('结论',r'f(x,0)>0,\quad f(0,y)<0\quad(x,y\neq0)'),T('原点是鞍点','不是极大点，也不是极小点')],[P('判别量是负四，所以原点是鞍点，不是极值点。直接核对也一样：沿x轴附近值大于零，沿y轴附近值小于零，而原点为零。第一步偏导为零只确定它是候选，不能跳过后面的判别。在解答题中把二阶数据、判别量及最终分类写完整，步骤清楚比只写一个名词更稳妥。',[1,2,3],['D小于零，判鞍点','驻点并不等于极值点'])],['二阶极值判别'],kind='answer')
